fn test_mask8x8() {
	for seed in 0 .. 8 {
		p := bools(8, seed)
		q := bools(8, seed + 8)
		mut pa := [8]bool{}
		mut qa := [8]bool{}
		for i in 0 .. 8 {
			pa[i] = p[i]
			qa[i] = q[i]
		}
		m := simd.from_array_mask8x8(pa)
		o := simd.from_array_mask8x8(qa)
		check_mask('Mask8x8 to_array', m.to_array()[..], p)
		assert m.all() == p.all(it)
		assert m.any() == p.any(it)
		assert m.count() == p.filter(it).len
		check_mask('Mask8x8 and', m.and(o).to_array()[..], []bool{len: 8, init: p[index] && q[index]})
		check_mask('Mask8x8 or', m.or(o).to_array()[..], []bool{len: 8, init: p[index] || q[index]})
		check_mask('Mask8x8 xor', m.xor(o).to_array()[..], []bool{len: 8, init: p[index] != q[index]})
		check_mask('Mask8x8 not', m.not().to_array()[..], p.map(!it))
		mut mm := m
		mm[7] = !p[7]
		assert mm[7] == !p[7]
		assert mm[0] == (p[0] != (7 == 0))
	}
	assert simd.splat_mask8x8(true).all()
	assert !simd.splat_mask8x8(false).any()
}

