fn test_f32x2() {
	a := pool_f32(5, [f32(0.0), -0.0, 1.5, -2.25, f32(math.inf(1)), f32(math.inf(-1)), f32(math.nan()),
		3.0, f32(math.nan()), 1.0, -0.0, 2.0])
	b := pool_f32(6, [f32(-0.0), 0.0, f32(math.nan()), 2.0, f32(math.inf(1)), 1.0, f32(math.nan()),
		f32(math.inf(-1)), 5.0, 1.0, -0.0, -2.0])
	cv := pool_f32(2, [f32(3e9), -3e9, 2147483520.0, -2147483648.0, 4294967040.0, 4294967296.0,
		1e20, -1e20, f32(math.nan()), f32(math.inf(1)), f32(math.inf(-1)), -0.5, 0.75, -1.0, 9.2e18,
		-9.3e18, 1.9e19, 2.5])
	nz := b
	for off := 0; off + 2 <= a.len; off += 3 {
		x := a[off..off + 2]
		y := b[off..off + 2]
		z := nz[off..off + 2]
		va := simd.load_f32x2_at(a, off)
		vb := simd.load_f32x2_at(b, off)
		vz := simd.load_f32x2_at(nz, off)
		check_f32('F32x2 load_at', va.to_array()[..], x)
		check_f32('F32x2 +', (va + vb).to_array()[..], ref2_f32('add', x, y))
		check_f32('F32x2 add', va.add(vb).to_array()[..], ref2_f32('add', x, y))
		check_f32('F32x2 -', (va - vb).to_array()[..], ref2_f32('sub', x, y))
		check_f32('F32x2 sub', va.sub(vb).to_array()[..], ref2_f32('sub', x, y))
		check_f32('F32x2 *', (va * vb).to_array()[..], ref2_f32('mul', x, y))
		check_f32('F32x2 mul', va.mul(vb).to_array()[..], ref2_f32('mul', x, y))
		check_f32('F32x2 /', (va / vz).to_array()[..], ref2_f32('div', x, z))
		check_f32('F32x2 div', va.div(vz).to_array()[..], ref2_f32('div', x, z))
		check_f32('F32x2 minimum', va.minimum(vb).to_array()[..], ref2_f32('min', x, y))
		check_f32('F32x2 maximum', va.maximum(vb).to_array()[..], ref2_f32('max', x, y))
		check_f32('F32x2 mul_add', va.mul_add(vb, vz).to_array()[..], ref2_f32('add', ref2_f32('mul', x, y), z))
		check_f32('F32x2 neg', va.neg().to_array()[..], ref1_f32('neg', x))
		check_f32('F32x2 abs', va.abs().to_array()[..], ref1_f32('abs', x))
		check_f32('F32x2 sqrt', va.sqrt().to_array()[..], ref1_f32('sqrt', x))
		check_mask('F32x2 eq', va.eq(vb).to_array()[..], refc_f32('eq', x, y))
		check_mask('F32x2 ne', va.ne(vb).to_array()[..], refc_f32('ne', x, y))
		check_mask('F32x2 lt', va.lt(vb).to_array()[..], refc_f32('lt', x, y))
		check_mask('F32x2 le', va.le(vb).to_array()[..], refc_f32('le', x, y))
		check_mask('F32x2 gt', va.gt(vb).to_array()[..], refc_f32('gt', x, y))
		check_mask('F32x2 ge', va.ge(vb).to_array()[..], refc_f32('ge', x, y))
		ml := va.lt(vb)
		bl := refc_f32('lt', x, y)
		check_f32('F32x2 select', simd.select_f32x2(ml, va, vb).to_array()[..], refsel_f32(bl, x, y))
		assert ml.count() == bl.filter(it).len
		assert ml.all() == bl.all(it)
		assert ml.any() == bl.any(it)
		check_f32('F32x2 sum', [va.sum()], [refsum_f32(x)])
		check_f32('F32x2 dot', [va.dot(vb)], [refdot_f32(x, y)])
		assert va.min_element() == refidx_f32(x, true)
		assert va.max_element() == refidx_f32(x, false)
		check_f32('F32x2 min', [va.min()], [x[refidx_f32(x, true)]])
		check_f32('F32x2 max', [va.max()], [x[refidx_f32(x, false)]])
		vc := simd.load_f32x2_at(cv, off % (cv.len - 1))
		check_i32('F32x2 to_i32x2', vc.to_i32x2().to_array()[..], refconv_f32_i32(vc.to_array()[..]))
		check_u32('F32x2 to_u32x2', vc.to_u32x2().to_array()[..], refconv_f32_u32(vc.to_array()[..]))
		mut vl := va
		vl[1] = y[0]
		check_f32('F32x2 []', [vl[0], vl[1]], [x[0], y[0]])
		mut dst := []f32{len: 4}
		va.store_at(mut dst, 1)
		check_f32('F32x2 store_at', dst[1..3], x)
	}
	check_f32('F32x2 splat', simd.splat_f32x2(a[2]).to_array()[..], []f32{len: 2, init: a[2]})
	mut fa := [2]f32{}
	for i in 0 .. 2 {
		fa[i] = a[i]
	}
	check_f32('F32x2 from_array', simd.from_array_f32x2(fa).to_array()[..], a[..2])
	check_f32('F32x2 f32x2', simd.f32x2(a[0], a[1]).to_array()[..], a[..2])
	vl := simd.load_f32x2(a) or { panic(err) }
	check_f32('F32x2 load', vl.to_array()[..], a[..2])
	vp := simd.load_f32x2_part(a[..1]) or { panic(err) }
	mut want := a[..1].clone()
	want << []f32{len: 1}
	check_f32('F32x2 load_part', vp.to_array()[..], want)
	mut out := []f32{len: 2}
	vl.store(mut out) or { panic(err) }
	check_f32('F32x2 store', out, a[..2])
	mut tail := []f32{len: 1}
	vl.store_part(mut tail) or { panic(err) }
	check_f32('F32x2 store_part', tail, a[..1])
	if _ := simd.load_f32x2(a[..1]) {
		assert false
	}
	if _ := simd.load_f32x2_part(a[..3]) {
		assert false
	}
	vl.store(mut tail) or { tail.clear() }
	assert tail.len == 0
	mut long := []f32{len: 3}
	vl.store_part(mut long) or { long.clear() }
	assert long.len == 0
}

