	vl := simd.load_f32x4(a) or { panic(err) }
	check_f32('F32x4 load', vl.to_array()[..], a[..4])
	vp := simd.load_f32x4_part(a[..2]) or { panic(err) }
	mut want := a[..2].clone()
	want << []f32{len: 2}
	check_f32('F32x4 load_part', vp.to_array()[..], want)
	mut out := []f32{len: 4}
	vl.store(mut out) or { panic(err) }
	check_f32('F32x4 store', out, a[..4])
	mut tail := []f32{len: 2}
	vl.store_part(mut tail) or { panic(err) }
	check_f32('F32x4 store_part', tail, a[..2])
