		3.0, f64(math.nan()), 1.0, -0.0, 2.0])
	b := pool_f64(10, [f64(-0.0), 0.0, f64(math.nan()), 2.0, f64(math.inf(1)), 1.0, f64(math.nan()),
		f64(math.inf(-1)), 5.0, 1.0, -0.0, -2.0])
	cv := pool_f64(4, [f64(3e9), -3e9, 2147483520.0, -2147483648.0, 4294967040.0, 4294967296.0,
		1e20, -1e20, f64(math.nan()), f64(math.inf(1)), f64(math.inf(-1)), -0.5, 0.75, -1.0, 9.2e18,
		-9.3e18, 1.9e19, 2.5])
	nz := b
	for off := 0; off + 4 <= a.len; off += 3 {
		x := a[off..off + 4]
		y := b[off..off + 4]
		z := nz[off..off + 4]
		va := simd.load_f64x4_at(a, off)
		vb := simd.load_f64x4_at(b, off)
		vz := simd.load_f64x4_at(nz, off)
		check_f64('F64x4 load_at', va.to_array()[..], x)
		check_f64('F64x4 +', (va + vb).to_array()[..], ref2_f64('add', x, y))
		check_f64('F64x4 add', va.add(vb).to_array()[..], ref2_f64('add', x, y))
		check_f64('F64x4 -', (va - vb).to_array()[..], ref2_f64('sub', x, y))
		check_f64('F64x4 sub', va.sub(vb).to_array()[..], ref2_f64('sub', x, y))
		check_f64('F64x4 *', (va * vb).to_array()[..], ref2_f64('mul', x, y))
		check_f64('F64x4 mul', va.mul(vb).to_array()[..], ref2_f64('mul', x, y))
		check_f64('F64x4 /', (va / vz).to_array()[..], ref2_f64('div', x, z))
		check_f64('F64x4 div', va.div(vz).to_array()[..], ref2_f64('div', x, z))
		check_f64('F64x4 minimum', va.minimum(vb).to_array()[..], ref2_f64('min', x, y))
		check_f64('F64x4 maximum', va.maximum(vb).to_array()[..], ref2_f64('max', x, y))
		check_f64('F64x4 mul_add', va.mul_add(vb, vz).to_array()[..], ref2_f64('add', ref2_f64('mul', x, y), z))
		check_f64('F64x4 neg', va.neg().to_array()[..], ref1_f64('neg', x))
		check_f64('F64x4 abs', va.abs().to_array()[..], ref1_f64('abs', x))
		check_f64('F64x4 sqrt', va.sqrt().to_array()[..], ref1_f64('sqrt', x))
		check_mask('F64x4 eq', va.eq(vb).to_array()[..], refc_f64('eq', x, y))
		check_mask('F64x4 ne', va.ne(vb).to_array()[..], refc_f64('ne', x, y))
		check_mask('F64x4 lt', va.lt(vb).to_array()[..], refc_f64('lt', x, y))
		check_mask('F64x4 le', va.le(vb).to_array()[..], refc_f64('le', x, y))
		check_mask('F64x4 gt', va.gt(vb).to_array()[..], refc_f64('gt', x, y))
		check_mask('F64x4 ge', va.ge(vb).to_array()[..], refc_f64('ge', x, y))
		ml := va.lt(vb)
		bl := refc_f64('lt', x, y)
		check_f64('F64x4 select', simd.select_f64x4(ml, va, vb).to_array()[..], refsel_f64(bl, x, y))
		assert ml.count() == bl.filter(it).len
		assert ml.all() == bl.all(it)
		assert ml.any() == bl.any(it)
		check_f64('F64x4 sum', [va.sum()], [refsum_f64(x)])
		check_f64('F64x4 dot', [va.dot(vb)], [refdot_f64(x, y)])
		assert va.min_element() == refidx_f64(x, true)
		assert va.max_element() == refidx_f64(x, false)
		check_f64('F64x4 min', [va.min()], [x[refidx_f64(x, true)]])
		check_f64('F64x4 max', [va.max()], [x[refidx_f64(x, false)]])
		vc := simd.load_f64x4_at(cv, off % (cv.len - 3))
		check_i64('F64x4 to_i64x4', vc.to_i64x4().to_array()[..], refconv_f64_i64(vc.to_array()[..]))
		check_u64('F64x4 to_u64x4', vc.to_u64x4().to_array()[..], refconv_f64_u64(vc.to_array()[..]))
		mut vl := va
		vl[3] = y[0]
		check_f64('F64x4 []', [vl[0], vl[3]], [x[0], y[0]])
		mut dst := []f64{len: 6}
		va.store_at(mut dst, 1)
		check_f64('F64x4 store_at', dst[1..5], x)
	}
	check_f64('F64x4 splat', simd.splat_f64x4(a[2]).to_array()[..], []f64{len: 4, init: a[2]})
	mut fa := [4]f64{}
	for i in 0 .. 4 {
		fa[i] = a[i]
	}
	check_f64('F64x4 from_array', simd.from_array_f64x4(fa).to_array()[..], a[..4])
	check_f64('F64x4 f64x4', simd.f64x4(a[0], a[1], a[2], a[3]).to_array()[..], a[..4])
	vl := simd.load_f64x4(a) or { panic(err) }
	check_f64('F64x4 load', vl.to_array()[..], a[..4])
	vp := simd.load_f64x4_part(a[..2]) or { panic(err) }
	mut want := a[..2].clone()
	want << []f64{len: 2}
	check_f64('F64x4 load_part', vp.to_array()[..], want)
	mut out := []f64{len: 4}
	vl.store(mut out) or { panic(err) }
	check_f64('F64x4 store', out, a[..4])
	mut tail := []f64{len: 2}
	vl.store_part(mut tail) or { panic(err) }
	check_f64('F64x4 store_part', tail, a[..2])
	if _ := simd.load_f64x4(a[..3]) {
		assert false
	}
	if _ := simd.load_f64x4_part(a[..5]) {
		assert false
	}
	vl.store(mut tail) or { tail.clear() }
	assert tail.len == 0
	mut long := []f64{len: 5}
	vl.store_part(mut long) or { long.clear() }
	assert long.len == 0
}

