fn test_i8x8() {
	a := pool_i8(17, [min_i8, min_i8, max_i8, max_i8, 0, -1, 1, min_i8 + 1, max_i8 - 1, 2, -2,
		0])
	b := pool_i8(18, [i8(-1), 1, 1, -1, min_i8, max_i8, -1, 2, -2, min_i8, 0, 0])
	nz := b.map(if it == 0 { i8(3) } else { it })
	for off := 0; off + 8 <= a.len; off += 3 {
