		check_mask('I16x8 ne', va.ne(vb).to_array()[..], refc_i16('ne', x, y))
		check_mask('I16x8 lt', va.lt(vb).to_array()[..], refc_i16('lt', x, y))
		check_mask('I16x8 le', va.le(vb).to_array()[..], refc_i16('le', x, y))
		check_mask('I16x8 gt', va.gt(vb).to_array()[..], refc_i16('gt', x, y))
		check_mask('I16x8 ge', va.ge(vb).to_array()[..], refc_i16('ge', x, y))
		ml := va.lt(vb)
		bl := refc_i16('lt', x, y)
		check_i16('I16x8 select', simd.select_i16x8(ml, va, vb).to_array()[..], refsel_i16(bl, x, y))
		assert ml.count() == bl.filter(it).len
		assert ml.all() == bl.all(it)
		assert ml.any() == bl.any(it)
		check_i16('I16x8 sum', [va.sum()], [refsum_i16(x)])
		check_i16('I16x8 dot', [va.dot(vb)], [refdot_i16(x, y)])
		assert va.min_element() == refidx_i16(x, true)
		assert va.max_element() == refidx_i16(x, false)
		check_i16('I16x8 min', [va.min()], [x[refidx_i16(x, true)]])
		check_i16('I16x8 max', [va.max()], [x[refidx_i16(x, false)]])
		check_u16('I16x8 to_u16x8', va.to_u16x8().to_array()[..], x.map(u16(it)))
		mut vl := va
		vl[7] = y[0]
		check_i16('I16x8 []', [vl[0], vl[7]], [x[0], y[0]])
		mut dst := []i16{len: 10}
		va.store_at(mut dst, 1)
		check_i16('I16x8 store_at', dst[1..9], x)
	}
	check_i16('I16x8 splat', simd.splat_i16x8(a[2]).to_array()[..], []i16{len: 8, init: a[2]})
	mut fa := [8]i16{}
	for i in 0 .. 8 {
		fa[i] = a[i]
	}
	check_i16('I16x8 from_array', simd.from_array_i16x8(fa).to_array()[..], a[..8])
	check_i16('I16x8 i16x8', simd.i16x8(a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7]).to_array()[..], a[..8])
	vl := simd.load_i16x8(a) or { panic(err) }
	check_i16('I16x8 load', vl.to_array()[..], a[..8])
	vp := simd.load_i16x8_part(a[..4]) or { panic(err) }
	mut want := a[..4].clone()
	want << []i16{len: 4}
	check_i16('I16x8 load_part', vp.to_array()[..], want)
	mut out := []i16{len: 8}
	vl.store(mut out) or { panic(err) }
	check_i16('I16x8 store', out, a[..8])
	mut tail := []i16{len: 4}
	vl.store_part(mut tail) or { panic(err) }
	check_i16('I16x8 store_part', tail, a[..4])
	if _ := simd.load_i16x8(a[..7]) {
		assert false
	}
	if _ := simd.load_i16x8_part(a[..9]) {
		assert false
	}
	vl.store(mut tail) or { tail.clear() }
	assert tail.len == 0
	mut long := []i16{len: 9}
	vl.store_part(mut long) or { long.clear() }
	assert long.len == 0
}

