	check_i32('I32x2 store', out, a[..2])
	mut tail := []i32{len: 1}
	vl.store_part(mut tail) or { panic(err) }
	check_i32('I32x2 store_part', tail, a[..1])
	if _ := simd.load_i32x2(a[..1]) {
		assert false
	}
	if _ := simd.load_i32x2_part(a[..3]) {
		assert false
	}
	vl.store(mut tail) or { tail.clear() }
	assert tail.len == 0
	mut long := []i32{len: 3}
	vl.store_part(mut long) or { long.clear() }
	assert long.len == 0
}

fn test_i32x4() {
	a := pool_i32(9, [min_i32, min_i32, max_i32, max_i32, 0, -1, 1, min_i32 + 1, max_i32 - 1, 2,
		-2, 0])
	b := pool_i32(10, [i32(-1), 1, 1, -1, min_i32, max_i32, -1, 2, -2, min_i32, 0, 0])
	nz := b.map(if it == 0 { i32(3) } else { it })
	for off := 0; off + 4 <= a.len; off += 3 {
		x := a[off..off + 4]
		y := b[off..off + 4]
		z := nz[off..off + 4]
		va := simd.load_i32x4_at(a, off)
		vb := simd.load_i32x4_at(b, off)
		vz := simd.load_i32x4_at(nz, off)
		check_i32('I32x4 load_at', va.to_array()[..], x)
		check_i32('I32x4 +', (va + vb).to_array()[..], ref2_i32('add', x, y))
		check_i32('I32x4 add', va.add(vb).to_array()[..], ref2_i32('add', x, y))
		check_i32('I32x4 -', (va - vb).to_array()[..], ref2_i32('sub', x, y))
		check_i32('I32x4 sub', va.sub(vb).to_array()[..], ref2_i32('sub', x, y))
		check_i32('I32x4 *', (va * vb).to_array()[..], ref2_i32('mul', x, y))
		check_i32('I32x4 mul', va.mul(vb).to_array()[..], ref2_i32('mul', x, y))
		check_i32('I32x4 /', (va / vz).to_array()[..], ref2_i32('div', x, z))
		check_i32('I32x4 div', va.div(vz).to_array()[..], ref2_i32('div', x, z))
		check_i32('I32x4 minimum', va.minimum(vb).to_array()[..], ref2_i32('min', x, y))
		check_i32('I32x4 maximum', va.maximum(vb).to_array()[..], ref2_i32('max', x, y))
		check_i32('I32x4 and', va.and(vb).to_array()[..], ref2_i32('and', x, y))
		check_i32('I32x4 or', va.or(vb).to_array()[..], ref2_i32('or', x, y))
		check_i32('I32x4 xor', va.xor(vb).to_array()[..], ref2_i32('xor', x, y))
		for c in [u32(0), 1, 31, 32, 35, 1000] {
			check_i32('I32x4 shl', va.shl(c).to_array()[..], refsh_i32(true, x, c))
			check_i32('I32x4 shr', va.shr(c).to_array()[..], refsh_i32(false, x, c))
		}
		check_i32('I32x4 neg', va.neg().to_array()[..], ref1_i32('neg', x))
		check_i32('I32x4 abs', va.abs().to_array()[..], ref1_i32('abs', x))
		check_i32('I32x4 not', va.not().to_array()[..], ref1_i32('not', x))
		check_mask('I32x4 eq', va.eq(vb).to_array()[..], refc_i32('eq', x, y))
		check_mask('I32x4 ne', va.ne(vb).to_array()[..], refc_i32('ne', x, y))
		check_mask('I32x4 lt', va.lt(vb).to_array()[..], refc_i32('lt', x, y))
		check_mask('I32x4 le', va.le(vb).to_array()[..], refc_i32('le', x, y))
		check_mask('I32x4 gt', va.gt(vb).to_array()[..], refc_i32('gt', x, y))
		check_mask('I32x4 ge', va.ge(vb).to_array()[..], refc_i32('ge', x, y))
		ml := va.lt(vb)
		bl := refc_i32('lt', x, y)
		check_i32('I32x4 select', simd.select_i32x4(ml, va, vb).to_array()[..], refsel_i32(bl, x, y))
		assert ml.count() == bl.filter(it).len
		assert ml.all() == bl.all(it)
		assert ml.any() == bl.any(it)
		check_i32('I32x4 sum', [va.sum()], [refsum_i32(x)])
		check_i32('I32x4 dot', [va.dot(vb)], [refdot_i32(x, y)])
		assert va.min_element() == refidx_i32(x, true)
		assert va.max_element() == refidx_i32(x, false)
		check_i32('I32x4 min', [va.min()], [x[refidx_i32(x, true)]])
		check_i32('I32x4 max', [va.max()], [x[refidx_i32(x, false)]])
		check_f32('I32x4 to_f32x4', va.to_f32x4().to_array()[..], x.map(f32(it)))
		check_u32('I32x4 to_u32x4', va.to_u32x4().to_array()[..], x.map(u32(it)))
		mut vl := va
		vl[3] = y[0]
		check_i32('I32x4 []', [vl[0], vl[3]], [x[0], y[0]])
		mut dst := []i32{len: 6}
		va.store_at(mut dst, 1)
		check_i32('I32x4 store_at', dst[1..5], x)
	}
	check_i32('I32x4 splat', simd.splat_i32x4(a[2]).to_array()[..], []i32{len: 4, init: a[2]})
	mut fa := [4]i32{}
	for i in 0 .. 4 {
		fa[i] = a[i]
	}
	check_i32('I32x4 from_array', simd.from_array_i32x4(fa).to_array()[..], a[..4])
	check_i32('I32x4 i32x4', simd.i32x4(a[0], a[1], a[2], a[3]).to_array()[..], a[..4])
	vl := simd.load_i32x4(a) or { panic(err) }
	check_i32('I32x4 load', vl.to_array()[..], a[..4])
	vp := simd.load_i32x4_part(a[..2]) or { panic(err) }
	mut want := a[..2].clone()
	want << []i32{len: 2}
	check_i32('I32x4 load_part', vp.to_array()[..], want)
	mut out := []i32{len: 4}
	vl.store(mut out) or { panic(err) }
	check_i32('I32x4 store', out, a[..4])
	mut tail := []i32{len: 2}
	vl.store_part(mut tail) or { panic(err) }
	check_i32('I32x4 store_part', tail, a[..2])
	if _ := simd.load_i32x4(a[..3]) {
		assert false
	}
	if _ := simd.load_i32x4_part(a[..5]) {
		assert false
	}
	vl.store(mut tail) or { tail.clear() }
	assert tail.len == 0
	mut long := []i32{len: 5}
	vl.store_part(mut long) or { long.clear() }
	assert long.len == 0
}

