		fa[i] = a[i]
	}
	check_i64('I64x2 from_array', simd.from_array_i64x2(fa).to_array()[..], a[..2])
	check_i64('I64x2 i64x2', simd.i64x2(a[0], a[1]).to_array()[..], a[..2])
	vl := simd.load_i64x2(a) or { panic(err) }
	check_i64('I64x2 load', vl.to_array()[..], a[..2])
	vp := simd.load_i64x2_part(a[..1]) or { panic(err) }
	mut want := a[..1].clone()
	want << []i64{len: 1}
	check_i64('I64x2 load_part', vp.to_array()[..], want)
	mut out := []i64{len: 2}
	vl.store(mut out) or { panic(err) }
	check_i64('I64x2 store', out, a[..2])
	mut tail := []i64{len: 1}
	vl.store_part(mut tail) or { panic(err) }
	check_i64('I64x2 store_part', tail, a[..1])
	if _ := simd.load_i64x2(a[..1]) {
		assert false
	}
	if _ := simd.load_i64x2_part(a[..3]) {
		assert false
	}
	vl.store(mut tail) or { tail.clear() }
	assert tail.len == 0
	mut long := []i64{len: 3}
	vl.store_part(mut long) or { long.clear() }
	assert long.len == 0
}

fn test_i64x4() {
	a := pool_i64(9, [min_i64, min_i64, max_i64, max_i64, 0, -1, 1, min_i64 + 1, max_i64 - 1, 2,
		-2, 0])
	b := pool_i64(10, [i64(-1), 1, 1, -1, min_i64, max_i64, -1, 2, -2, min_i64, 0, 0])
	nz := b.map(if it == 0 { i64(3) } else { it })
	for off := 0; off + 4 <= a.len; off += 3 {
		x := a[off..off + 4]
		y := b[off..off + 4]
		z := nz[off..off + 4]
		va := simd.load_i64x4_at(a, off)
		vb := simd.load_i64x4_at(b, off)
		vz := simd.load_i64x4_at(nz, off)
