		check_i64('I64x4 +', (va + vb).to_array()[..], ref2_i64('add', x, y))
		check_i64('I64x4 add', va.add(vb).to_array()[..], ref2_i64('add', x, y))
		check_i64('I64x4 -', (va - vb).to_array()[..], ref2_i64('sub', x, y))
		check_i64('I64x4 sub', va.sub(vb).to_array()[..], ref2_i64('sub', x, y))
