		check_i64('I64x4 mul', va.mul(vb).to_array()[..], ref2_i64('mul', x, y))
		check_i64('I64x4 /', (va / vz).to_array()[..], ref2_i64('div', x, z))
		check_i64('I64x4 div', va.div(vz).to_array()[..], ref2_i64('div', x, z))
		check_i64('I64x4 minimum', va.minimum(vb).to_array()[..], ref2_i64('min', x, y))
		check_i64('I64x4 maximum', va.maximum(vb).to_array()[..], ref2_i64('max', x, y))
