		check_i64('I64x4 or', va.or(vb).to_array()[..], ref2_i64('or', x, y))
		check_i64('I64x4 xor', va.xor(vb).to_array()[..], ref2_i64('xor', x, y))
		for c in [u32(0), 1, 63, 64, 67, 1000] {
			check_i64('I64x4 shl', va.shl(c).to_array()[..], refsh_i64(true, x, c))
			check_i64('I64x4 shr', va.shr(c).to_array()[..], refsh_i64(false, x, c))
		}
		check_i64('I64x4 neg', va.neg().to_array()[..], ref1_i64('neg', x))
		check_i64('I64x4 abs', va.abs().to_array()[..], ref1_i64('abs', x))
		check_i64('I64x4 not', va.not().to_array()[..], ref1_i64('not', x))
		check_mask('I64x4 eq', va.eq(vb).to_array()[..], refc_i64('eq', x, y))
		check_mask('I64x4 ne', va.ne(vb).to_array()[..], refc_i64('ne', x, y))
		check_mask('I64x4 lt', va.lt(vb).to_array()[..], refc_i64('lt', x, y))
		check_mask('I64x4 le', va.le(vb).to_array()[..], refc_i64('le', x, y))
		check_mask('I64x4 gt', va.gt(vb).to_array()[..], refc_i64('gt', x, y))
		check_mask('I64x4 ge', va.ge(vb).to_array()[..], refc_i64('ge', x, y))
		ml := va.lt(vb)
		bl := refc_i64('lt', x, y)
		check_i64('I64x4 select', simd.select_i64x4(ml, va, vb).to_array()[..], refsel_i64(bl, x, y))
		assert ml.count() == bl.filter(it).len
		assert ml.all() == bl.all(it)
		assert ml.any() == bl.any(it)
		check_i64('I64x4 sum', [va.sum()], [refsum_i64(x)])
		check_i64('I64x4 dot', [va.dot(vb)], [refdot_i64(x, y)])
		assert va.min_element() == refidx_i64(x, true)
		assert va.max_element() == refidx_i64(x, false)
		check_i64('I64x4 min', [va.min()], [x[refidx_i64(x, true)]])
		check_i64('I64x4 max', [va.max()], [x[refidx_i64(x, false)]])
		check_f64('I64x4 to_f64x4', va.to_f64x4().to_array()[..], x.map(f64(it)))
		check_u64('I64x4 to_u64x4', va.to_u64x4().to_array()[..], x.map(u64(it)))
		mut vl := va
		vl[3] = y[0]
		check_i64('I64x4 []', [vl[0], vl[3]], [x[0], y[0]])
		mut dst := []i64{len: 6}
		va.store_at(mut dst, 1)
		check_i64('I64x4 store_at', dst[1..5], x)
