	check_i64('I64x4 splat', simd.splat_i64x4(a[2]).to_array()[..], []i64{len: 4, init: a[2]})
	mut fa := [4]i64{}
	for i in 0 .. 4 {
		fa[i] = a[i]
	}
	check_i64('I64x4 from_array', simd.from_array_i64x4(fa).to_array()[..], a[..4])
	check_i64('I64x4 i64x4', simd.i64x4(a[0], a[1], a[2], a[3]).to_array()[..], a[..4])
	vl := simd.load_i64x4(a) or { panic(err) }
	check_i64('I64x4 load', vl.to_array()[..], a[..4])
	vp := simd.load_i64x4_part(a[..2]) or { panic(err) }
	mut want := a[..2].clone()
	want << []i64{len: 2}
	check_i64('I64x4 load_part', vp.to_array()[..], want)
	mut out := []i64{len: 4}
	vl.store(mut out) or { panic(err) }
	check_i64('I64x4 store', out, a[..4])
	mut tail := []i64{len: 2}
	vl.store_part(mut tail) or { panic(err) }
	check_i64('I64x4 store_part', tail, a[..2])
	if _ := simd.load_i64x4(a[..3]) {
		assert false
	}
	if _ := simd.load_i64x4_part(a[..5]) {
		assert false
	}
	vl.store(mut tail) or { tail.clear() }
	assert tail.len == 0
	mut long := []i64{len: 5}
	vl.store_part(mut long) or { long.clear() }
	assert long.len == 0
}

