fn test_u8x16() {
	a := pool_u8(33, [u8(0), 1, max_u8, max_u8, max_u8 - 1, 2, max_u8 / 2, 0, 1])
	b := pool_u8(34, [u8(1), max_u8, max_u8, 2, 0, max_u8, 3, 0, 0])
	nz := b.map(if it == 0 { u8(3) } else { it })
	for off := 0; off + 16 <= a.len; off += 3 {
		x := a[off..off + 16]
		y := b[off..off + 16]
		z := nz[off..off + 16]
		va := simd.load_u8x16_at(a, off)
		vb := simd.load_u8x16_at(b, off)
		vz := simd.load_u8x16_at(nz, off)
		check_u8('U8x16 load_at', va.to_array()[..], x)
		check_u8('U8x16 +', (va + vb).to_array()[..], ref2_u8('add', x, y))
		check_u8('U8x16 add', va.add(vb).to_array()[..], ref2_u8('add', x, y))
		check_u8('U8x16 -', (va - vb).to_array()[..], ref2_u8('sub', x, y))
		check_u8('U8x16 sub', va.sub(vb).to_array()[..], ref2_u8('sub', x, y))
		check_u8('U8x16 *', (va * vb).to_array()[..], ref2_u8('mul', x, y))
		check_u8('U8x16 mul', va.mul(vb).to_array()[..], ref2_u8('mul', x, y))
		check_u8('U8x16 /', (va / vz).to_array()[..], ref2_u8('div', x, z))
		check_u8('U8x16 div', va.div(vz).to_array()[..], ref2_u8('div', x, z))
		check_u8('U8x16 minimum', va.minimum(vb).to_array()[..], ref2_u8('min', x, y))
		check_u8('U8x16 maximum', va.maximum(vb).to_array()[..], ref2_u8('max', x, y))
		check_u8('U8x16 and', va.and(vb).to_array()[..], ref2_u8('and', x, y))
		check_u8('U8x16 or', va.or(vb).to_array()[..], ref2_u8('or', x, y))
		check_u8('U8x16 xor', va.xor(vb).to_array()[..], ref2_u8('xor', x, y))
		for c in [u32(0), 1, 7, 8, 11, 1000] {
			check_u8('U8x16 shl', va.shl(c).to_array()[..], refsh_u8(true, x, c))
			check_u8('U8x16 shr', va.shr(c).to_array()[..], refsh_u8(false, x, c))
		}
		check_u8('U8x16 not', va.not().to_array()[..], ref1_u8('not', x))
		check_mask('U8x16 eq', va.eq(vb).to_array()[..], refc_u8('eq', x, y))
		check_mask('U8x16 ne', va.ne(vb).to_array()[..], refc_u8('ne', x, y))
		check_mask('U8x16 lt', va.lt(vb).to_array()[..], refc_u8('lt', x, y))
		check_mask('U8x16 le', va.le(vb).to_array()[..], refc_u8('le', x, y))
		check_mask('U8x16 gt', va.gt(vb).to_array()[..], refc_u8('gt', x, y))
		check_mask('U8x16 ge', va.ge(vb).to_array()[..], refc_u8('ge', x, y))
		ml := va.lt(vb)
		bl := refc_u8('lt', x, y)
		check_u8('U8x16 select', simd.select_u8x16(ml, va, vb).to_array()[..], refsel_u8(bl, x, y))
		assert ml.count() == bl.filter(it).len
		assert ml.all() == bl.all(it)
		assert ml.any() == bl.any(it)
		check_u8('U8x16 sum', [va.sum()], [refsum_u8(x)])
		check_u8('U8x16 dot', [va.dot(vb)], [refdot_u8(x, y)])
		assert va.min_element() == refidx_u8(x, true)
		assert va.max_element() == refidx_u8(x, false)
		check_u8('U8x16 min', [va.min()], [x[refidx_u8(x, true)]])
		check_u8('U8x16 max', [va.max()], [x[refidx_u8(x, false)]])
		check_i8('U8x16 to_i8x16', va.to_i8x16().to_array()[..], x.map(i8(it)))
		mut vl := va
		vl[15] = y[0]
		check_u8('U8x16 []', [vl[0], vl[15]], [x[0], y[0]])
		mut dst := []u8{len: 18}
		va.store_at(mut dst, 1)
		check_u8('U8x16 store_at', dst[1..17], x)
	}
	check_u8('U8x16 splat', simd.splat_u8x16(a[2]).to_array()[..], []u8{len: 16, init: a[2]})
	mut fa := [16]u8{}
	for i in 0 .. 16 {
		fa[i] = a[i]
	}
	check_u8('U8x16 from_array', simd.from_array_u8x16(fa).to_array()[..], a[..16])
	vl := simd.load_u8x16(a) or { panic(err) }
	check_u8('U8x16 load', vl.to_array()[..], a[..16])
	vp := simd.load_u8x16_part(a[..8]) or { panic(err) }
	mut want := a[..8].clone()
	want << []u8{len: 8}
	check_u8('U8x16 load_part', vp.to_array()[..], want)
	mut out := []u8{len: 16}
	vl.store(mut out) or { panic(err) }
	check_u8('U8x16 store', out, a[..16])
	mut tail := []u8{len: 8}
	vl.store_part(mut tail) or { panic(err) }
	check_u8('U8x16 store_part', tail, a[..8])
	if _ := simd.load_u8x16(a[..15]) {
		assert false
	}
	if _ := simd.load_u8x16_part(a[..17]) {
		assert false
	}
	vl.store(mut tail) or { tail.clear() }
	assert tail.len == 0
	mut long := []u8{len: 17}
	vl.store_part(mut long) or { long.clear() }
	assert long.len == 0
}

