	mut tail := []u32{len: 1}
	vl.store_part(mut tail) or { panic(err) }
	check_u32('U32x2 store_part', tail, a[..1])
	if _ := simd.load_u32x2(a[..1]) {
		assert false
	}
	if _ := simd.load_u32x2_part(a[..3]) {
		assert false
	}
	vl.store(mut tail) or { tail.clear() }
	assert tail.len == 0
	mut long := []u32{len: 3}
	vl.store_part(mut long) or { long.clear() }
	assert long.len == 0
}

fn test_u32x4() {
	a := pool_u32(9, [u32(0), 1, max_u32, max_u32, max_u32 - 1, 2, max_u32 / 2, 0, 1])
	b := pool_u32(10, [u32(1), max_u32, max_u32, 2, 0, max_u32, 3, 0, 0])
