		check_mask('U32x4 gt', va.gt(vb).to_array()[..], refc_u32('gt', x, y))
		check_mask('U32x4 ge', va.ge(vb).to_array()[..], refc_u32('ge', x, y))
		ml := va.lt(vb)
		bl := refc_u32('lt', x, y)
