fn test_u64x2() {
	a := pool_u64(5, [u64(0), 1, max_u64, max_u64, max_u64 - 1, 2, max_u64 / 2, 0, 1])
	b := pool_u64(6, [u64(1), max_u64, max_u64, 2, 0, max_u64, 3, 0, 0])
	nz := b.map(if it == 0 { u64(3) } else { it })
	for off := 0; off + 2 <= a.len; off += 3 {
		x := a[off..off + 2]
		y := b[off..off + 2]
		z := nz[off..off + 2]
		va := simd.load_u64x2_at(a, off)
		vb := simd.load_u64x2_at(b, off)
		vz := simd.load_u64x2_at(nz, off)
		check_u64('U64x2 load_at', va.to_array()[..], x)
		check_u64('U64x2 +', (va + vb).to_array()[..], ref2_u64('add', x, y))
		check_u64('U64x2 add', va.add(vb).to_array()[..], ref2_u64('add', x, y))
		check_u64('U64x2 -', (va - vb).to_array()[..], ref2_u64('sub', x, y))
		check_u64('U64x2 sub', va.sub(vb).to_array()[..], ref2_u64('sub', x, y))
		check_u64('U64x2 *', (va * vb).to_array()[..], ref2_u64('mul', x, y))
		check_u64('U64x2 mul', va.mul(vb).to_array()[..], ref2_u64('mul', x, y))
		check_u64('U64x2 /', (va / vz).to_array()[..], ref2_u64('div', x, z))
		check_u64('U64x2 div', va.div(vz).to_array()[..], ref2_u64('div', x, z))
		check_u64('U64x2 minimum', va.minimum(vb).to_array()[..], ref2_u64('min', x, y))
		check_u64('U64x2 maximum', va.maximum(vb).to_array()[..], ref2_u64('max', x, y))
		check_u64('U64x2 and', va.and(vb).to_array()[..], ref2_u64('and', x, y))
		check_u64('U64x2 or', va.or(vb).to_array()[..], ref2_u64('or', x, y))
		check_u64('U64x2 xor', va.xor(vb).to_array()[..], ref2_u64('xor', x, y))
		for c in [u32(0), 1, 63, 64, 67, 1000] {
			check_u64('U64x2 shl', va.shl(c).to_array()[..], refsh_u64(true, x, c))
			check_u64('U64x2 shr', va.shr(c).to_array()[..], refsh_u64(false, x, c))
		}
		check_u64('U64x2 not', va.not().to_array()[..], ref1_u64('not', x))
		check_mask('U64x2 eq', va.eq(vb).to_array()[..], refc_u64('eq', x, y))
		check_mask('U64x2 ne', va.ne(vb).to_array()[..], refc_u64('ne', x, y))
		check_mask('U64x2 lt', va.lt(vb).to_array()[..], refc_u64('lt', x, y))
		check_mask('U64x2 le', va.le(vb).to_array()[..], refc_u64('le', x, y))
		check_mask('U64x2 gt', va.gt(vb).to_array()[..], refc_u64('gt', x, y))
		check_mask('U64x2 ge', va.ge(vb).to_array()[..], refc_u64('ge', x, y))
		ml := va.lt(vb)
		bl := refc_u64('lt', x, y)
		check_u64('U64x2 select', simd.select_u64x2(ml, va, vb).to_array()[..], refsel_u64(bl, x, y))
		assert ml.count() == bl.filter(it).len
		assert ml.all() == bl.all(it)
		assert ml.any() == bl.any(it)
		check_u64('U64x2 sum', [va.sum()], [refsum_u64(x)])
		check_u64('U64x2 dot', [va.dot(vb)], [refdot_u64(x, y)])
		assert va.min_element() == refidx_u64(x, true)
		assert va.max_element() == refidx_u64(x, false)
		check_u64('U64x2 min', [va.min()], [x[refidx_u64(x, true)]])
		check_u64('U64x2 max', [va.max()], [x[refidx_u64(x, false)]])
		check_f64('U64x2 to_f64x2', va.to_f64x2().to_array()[..], x.map(f64(it)))
		check_i64('U64x2 to_i64x2', va.to_i64x2().to_array()[..], x.map(i64(it)))
		mut vl := va
		vl[1] = y[0]
		check_u64('U64x2 []', [vl[0], vl[1]], [x[0], y[0]])
		mut dst := []u64{len: 4}
		va.store_at(mut dst, 1)
		check_u64('U64x2 store_at', dst[1..3], x)
	}
	check_u64('U64x2 splat', simd.splat_u64x2(a[2]).to_array()[..], []u64{len: 2, init: a[2]})
	mut fa := [2]u64{}
	for i in 0 .. 2 {
		fa[i] = a[i]
	}
	check_u64('U64x2 from_array', simd.from_array_u64x2(fa).to_array()[..], a[..2])
	check_u64('U64x2 u64x2', simd.u64x2(a[0], a[1]).to_array()[..], a[..2])
	vl := simd.load_u64x2(a) or { panic(err) }
	check_u64('U64x2 load', vl.to_array()[..], a[..2])
	vp := simd.load_u64x2_part(a[..1]) or { panic(err) }
	mut want := a[..1].clone()
	want << []u64{len: 1}
	check_u64('U64x2 load_part', vp.to_array()[..], want)
	mut out := []u64{len: 2}
	vl.store(mut out) or { panic(err) }
	check_u64('U64x2 store', out, a[..2])
	mut tail := []u64{len: 1}
	vl.store_part(mut tail) or { panic(err) }
	check_u64('U64x2 store_part', tail, a[..1])
	if _ := simd.load_u64x2(a[..1]) {
		assert false
	}
	if _ := simd.load_u64x2_part(a[..3]) {
		assert false
	}
	vl.store(mut tail) or { tail.clear() }
	assert tail.len == 0
	mut long := []u64{len: 3}
	vl.store_part(mut long) or { long.clear() }
	assert long.len == 0
}

